PREFIX brick: <https://brickschema.org/schema/1.5/brick#>
PREFIX ref: <http://xmlns.nanonames.org/ref#>
SELECT ?zone ?label ?ts WHERE {
  ?zone a brick:Zone ; rdfs:label ?label .
  ?zone ref:hasTimeseriesId ?ts .
} LIMIT 50

PREFIX brick: <https://brickschema.org/schema/1.5/brick#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?s ?label ?class WHERE {
  ?s ?p ?o .
  FILTER(CONTAINS(LCASE(STR(?s)), "ZN_2") || CONTAINS(LCASE(STR(?s)), "DataCenter"))
  ?s rdfs:label ?label .
  OPTIONAL { ?s a ?class }
} LIMIT 30

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT DISTINCT ?label WHERE {
  ?s rdfs:label ?label .
} LIMIT 200

